package com.sora.splineroads.client;
import com.sora.splineroads.SplineRoads;import com.sora.splineroads.core.*;import com.sora.splineroads.core.RoadGeometry.*;import com.sora.splineroads.world.*;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.registries.Registries;import net.minecraft.world.Difficulty;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.WorldOptions;import net.minecraft.world.level.levelgen.presets.WorldPresets;
import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=SplineRoads.ID,value=Dist.CLIENT)
public final class Audit201NativeVisual {
 private static final Path OUT=Path.of("feedback201-access-bridges");private static boolean started,done;private static int ticks,stage,ready,shot;private static long deadline;private static String save;private static CompletableFuture<Audit201VisualFixture.Scene> pending;private static Audit201VisualFixture.Scene scene;private static V focus,front;private static final List<String> measurements=new ArrayList<>();
 private static net.minecraft.server.level.ServerPlayer player(Minecraft mc){return mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());}
 private static net.minecraft.world.level.levelgen.WorldDimensions dimensions(net.minecraft.core.RegistryAccess r){var flat=net.minecraft.world.level.levelgen.flat.FlatLevelGeneratorSettings.getDefault(r.registryOrThrow(Registries.BIOME).asLookup(),r.registryOrThrow(Registries.STRUCTURE_SET).asLookup(),r.registryOrThrow(Registries.PLACED_FEATURE).asLookup());return r.registryOrThrow(Registries.WORLD_PRESET).getOrThrow(WorldPresets.FLAT).createWorldDimensions().replaceOverworldGenerator(r,new net.minecraft.world.level.levelgen.FlatLevelSource(flat));}
 private static Object field(Class<?> c,String name)throws Exception{var f=c.getDeclaredField(name);f.setAccessible(true);return f.get(null);}
 private static boolean settled()throws Exception{
  if(!((Map<?,?>)field(RoadRenderer.class,"jobs")).isEmpty()||field(RoadRenderer.class,"pendingUpload")!=null||SmartSignClient.pendingUploads())return false;
  for(var section:(List<?>)field(RoadRenderer.class,"visible")){var f=section.getClass().getDeclaredField("dirty");f.setAccessible(true);var k=section.getClass().getDeclaredField("key");k.setAccessible(true);if(f.getBoolean(section)&&RoadTerrainModels.regionLoaded((RoadRenderMesh.Section)k.get(section)))return false;}return true;
 }
 private static boolean signDrawn()throws Exception{return (Integer)field(SmartSignClient.class,"frameDrawn")>0&&((Map<?,?>)field(SmartSignClient.class,"cache")).containsKey(new SmartSigns.Key(scene.connector(),0,1));}
 private static void view(Minecraft mc,V eye,V target){var d=target.sub(eye);float yaw=(float)RoadPlanner.yaw(d),pitch=(float)-Math.toDegrees(Math.atan2(d.y(),d.horizontalLength()));mc.getSingleplayerServer().execute(()->{var p=player(mc);p.getAbilities().flying=true;p.setNoGravity(true);p.onUpdateAbilities();p.teleportTo(p.serverLevel(),eye.x(),eye.y(),eye.z(),yaw,pitch);});mc.player.setPos(eye.x(),eye.y(),eye.z());mc.player.setYRot(yaw);mc.player.yRotO=yaw;mc.player.setXRot(pitch);mc.player.xRotO=pitch;}
 private static void capture(Minecraft mc,String name)throws Exception{try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(OUT.resolve(name+".png"));}System.out.println("SR201 NATIVE CAPTURE "+name);}
 @SuppressWarnings("unchecked") private static boolean observeSign()throws Exception{
  var states=(Map<SmartSigns.Key,SmartSigns.State>)field(SmartSignClient.class,"states");var state=states.get(new SmartSigns.Key(scene.connector(),0,1));var host=ClientRoads.INDEX.roads.get(scene.host());var ramp=ClientRoads.INDEX.roads.get(scene.connector());if(state==null||state.support()==null||host==null||ramp==null)return false;if(!state.diagnostic().isEmpty()||state.branches().size()!=1)throw new AssertionError("client solo sign invalid: "+state);
  var layout=SmartSigns.layout(ramp.mesh,state);var board=layout.boards().stream().filter(b->b.branch().equals("elevated")).findFirst().orElseThrow();var center=layout.origin().add(layout.right().mul(board.x()));var projected=RoadQueries.horizontal(host.mesh,center).sample();var roadLayout=RoadProfile.layout(host.mesh,projected);var lane=LaneSections.live(host.mesh,projected.distance()).lanes().stream().filter(l->l.sign()==1).min(Comparator.comparingDouble(l->Math.abs(l.position().sub(projected.center()).dot(projected.left())-roadLayout.medianCenter()))).orElseThrow();double error=center.sub(lane.position()).horizontalLength();if(error>1e-6)throw new AssertionError("client board not on actual inner lane: "+error);
  focus=center.add(new V(0,board.bottom()+board.height()/2,0));front=layout.front();measurements.add("client received sign center="+center+" actual inner lane="+lane.position()+" horizontalError="+error+" state="+state.key());return true;
 }
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(!Boolean.getBoolean("road.audit201Visual")||done||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();ticks++;
  try{
   if(!started){if(!(mc.screen instanceof TitleScreen)||mc.getOverlay()!=null)return;started=true;Files.createDirectories(OUT);deadline=System.nanoTime()+900_000_000_000L;save="sr201-visual-"+System.currentTimeMillis();mc.getTutorial().setStep(net.minecraft.client.tutorial.TutorialSteps.NONE);mc.options.pauseOnLostFocus=false;mc.options.enableVsync().set(false);mc.options.renderDistance().set(10);mc.options.framerateLimit().set(60);mc.options.cloudStatus().set(CloudStatus.OFF);mc.options.guiScale().set(2);mc.resizeDisplay();mc.createWorldOpenFlows().createFreshLevel(save,new LevelSettings("SR201 isolated access bridges",GameType.CREATIVE,false,Difficulty.PEACEFUL,true,new GameRules(),WorldDataConfiguration.DEFAULT),new WorldOptions(201,false,false),Audit201NativeVisual::dimensions);return;}
   if(System.nanoTime()>deadline)throw new AssertionError("timeout stage="+stage);
   if(stage==7){if(mc.level!=null||mc.getSingleplayerServer()!=null||ticks<ready)return;mc.createWorldOpenFlows().loadLevel(new TitleScreen(),save);stage=8;ready=ticks+100;return;}
   if(mc.level==null||mc.player==null||mc.getOverlay()!=null||ticks<ready)return;mc.player.setDeltaMovement(0,0,0);mc.player.getAbilities().flying=true;mc.player.setNoGravity(true);
   if(stage==0){mc.setScreen(null);mc.options.hideGui=true;pending=mc.getSingleplayerServer().submit(()->{var p=player(mc);p.setGameMode(GameType.CREATIVE);p.getAbilities().flying=true;p.setNoGravity(true);p.onUpdateAbilities();p.serverLevel().setDayTime(6000);p.serverLevel().setWeatherParameters(6000,0,false,false);p.teleportTo(p.serverLevel(),.5,-50,85,0,0);return Audit201VisualFixture.create(p);});stage=1;return;}
   if(stage==1){if(!pending.isDone())return;scene=pending.join();view(mc,new V(.5,-50,80),new V(.5,-54,105));stage=2;ready=ticks+160;return;}
   if(stage==2){if(!settled()||!observeSign())return;view(mc,focus.add(front.mul(26)).add(new V(0,1,0)),focus);stage=3;ready=ticks+120;return;}
   if(stage==3){if(!settled()||!signDrawn())return;capture(mc,"01-sign-inner-lane-front");view(mc,new V(32,-25,100),new V(.5,-55,155));stage=4;ready=ticks+140;return;}
   if(stage==4){if(!settled())return;capture(mc,"02-single-aux-access");shot=0;var seam=scene.bridgeSeams().get(shot);view(mc,seam.add(new V(30,16,-28)),seam.add(new V(0,0,18)));stage=5;ready=ticks+160;return;}
   if(stage==5){if(!settled())return;String[] names={"03-arch-joined-seam","04-cable-joined-seam","05-suspension-joined-seam"};capture(mc,names[shot]);shot++;if(shot<3){var seam=scene.bridgeSeams().get(shot);view(mc,seam.add(new V(30,16,-28)),seam.add(new V(0,0,18)));ready=ticks+160;return;}mc.level.disconnect();mc.clearLevel();mc.setScreen(new TitleScreen());stage=7;ready=ticks+60;return;}
   if(stage==8){mc.setScreen(null);mc.options.hideGui=true;view(mc,new V(.5,-50,80),new V(.5,-54,105));stage=9;ready=ticks+160;return;}
   if(stage==9){if(!settled()||!observeSign())return;view(mc,focus.add(front.mul(26)).add(new V(0,1,0)),focus);stage=10;ready=ticks+120;return;}
   if(stage==10){if(!settled()||!signDrawn())return;capture(mc,"06-sign-after-world-reopen");measurements.add("PASS actual client build, received and drawn sign state, 3 bridge screenshots, single-aux screenshot and save/reopen sign verification. Screenshots require human/model inspection.");Files.write(OUT.resolve("measurements.txt"),measurements);System.out.println("SR201 NATIVE ACCESS BRIDGES PASS");done=true;mc.stop();}
  }catch(Throwable failure){done=true;failure.printStackTrace();try{Files.writeString(OUT.resolve("failure.txt"),"stage="+stage+" "+failure);}catch(Exception ignored){}mc.stop();}
 }
}
